#nullable enable // autogenerated

using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public class LanguagePackReaderZipV0 : LanguagePackReaderV0
    {
        public LanguagePackReaderZipV0(MainManager main) : base(main)
        {
        }
        public override LanguagePack? ReadPack(string key, string path)
        {
            using var stream = File.Open(path, FileMode.Open);
            return ReadPack(key, stream);
        }
        public LanguagePack? ReadPack(string key, byte[] bytes)
        {
            using var memory = new MemoryStream(bytes);
            return ReadPack(key, memory);
        }
        public LanguagePack? ReadPack(string key, Stream stream)
        {
            try
            {
                using var archive = new ZipArchive(stream);
                var languagePack = new LanguagePack(key);
                var entries = archive.Entries.ToArray();
                foreach (var entry in entries)
                {
                    if (string.IsNullOrEmpty(entry.Name))
                        continue;

                    if (string.IsNullOrEmpty(Path.GetExtension(entry.FullName)))
                        continue;

                    var fullPath = entry.FullName.Replace("\\", "/");
                    var splitedPaths = fullPath.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                    if (splitedPaths.Length < 3 || splitedPaths[0] != "assets")
                        continue;
                    var nsp = splitedPaths[1];
                    var lang = splitedPaths[2].Replace('_', '-');
                    if (splitedPaths.Length == 4)
                    {
                        string filename = splitedPaths[3];
                        var asset = languagePack.GetOrCreateLanguageAsset(lang);
                        if (Path.GetExtension(filename) == ".mo")
                        {
                            // 加载MO翻译文件。
                            var filenameWithoutExt = Path.GetFileNameWithoutExtension(filename);
                            var catalog = entry.ReadCatalog(lang);
                            asset.catalogs.Add(filenameWithoutExt, catalog);
                        }
                        else if (filename == SPRITE_MANIFEST_FILENAME)
                        {
                            // 加载Sprite Manifest文件。
                            var manifestJson = entry.ReadString(Encoding.UTF8);
                            var manifest = JsonConvert.DeserializeObject<LocalizedSpriteManifest>(manifestJson);
                            if (manifest != null)
                            {
                                // 加载Sprite。
                                if (manifest.sprites != null)
                                {
                                    foreach (var localizedSprite in manifest.sprites)
                                    {
                                        var texturePath = Path.Combine(splitedPaths[0], splitedPaths[1], splitedPaths[2], "sprites", localizedSprite.texture);
                                        var textureEntry = entries.FirstOrDefault(e => e.FullName.Replace("\\", "/") == texturePath.Replace("\\", "/"));

                                        if (textureEntry == null || string.IsNullOrEmpty(localizedSprite.name))
                                            continue;
                                        if (!asset.textures.TryGetValue(texturePath, out var texture2D))
                                        {
                                            texture2D = ReadTexture2DZip(textureEntry, texturePath);
                                            asset.textures.Add(texturePath, texture2D);
                                        }

                                        var resID = new NamespaceID(nsp, localizedSprite.name);
                                        var sprite = CreateSprite(resID, texture2D, localizedSprite, key);
                                        asset.Sprites.Add(new SpriteReference(resID), sprite);
                                    }
                                }
                                // 加载Spritesheet。
                                if (manifest.spritesheets != null)
                                {
                                    foreach (var localizedSpritesheet in manifest.spritesheets)
                                    {
                                        var texturePath = Path.Combine(splitedPaths[0], splitedPaths[1], splitedPaths[2], "spritesheets", localizedSpritesheet.texture);
                                        var textureEntry = entries.FirstOrDefault(e => e.FullName.Replace("\\", "/") == texturePath.Replace("\\", "/"));

                                        if (textureEntry == null || string.IsNullOrEmpty(localizedSpritesheet.name))
                                            continue;
                                        if (!asset.textures.TryGetValue(texturePath, out var texture2D))
                                        {
                                            texture2D = ReadTexture2DZip(textureEntry, texturePath);
                                            asset.textures.Add(texturePath, texture2D);
                                        }

                                        var resID = new NamespaceID(nsp, localizedSpritesheet.name);
                                        var spritesheet = CreateSpriteSheet(resID, texture2D, localizedSpritesheet, key);
                                        for (int i = 0; i < spritesheet.Length; i++)
                                        {
                                            var spriteRef = new SpriteReference(resID, i);
                                            asset.Sprites.Add(spriteRef, spritesheet[i]);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return languagePack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包Zip失败：{e}");
                return null;
            }
        }
        private Texture2D ReadTexture2DZip(ZipArchiveEntry textureEntry, string name = "texture2D")
        {
            var bytes = textureEntry.ReadBytes();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
